window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[276]={"id":"276","numero":276,"titre":"Hépatomégalie - masse abdominale","objectifs":[{"id":"276-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une masse abdominale","contenu":"<div class=\"notion-course\"><p>Une <span><span class=\"nc-blue nc-bold\">masse abdominale</span></span> se définit comme une <span><span class=\"nc-red\">augmentation de volume</span> d’un organe ou d’une région de l’abdomen</span>. Sa découverte impose une <span>analyse topographique</span> rigoureuse : la <span>masse</span> est rapportée à l’un des quadrants de la paroi abdominale, ce qui oriente d’emblée vers <span>les</span> organes sous-jacents et les étiologies possibles.</p>\n      <p>L’examen commence par éliminer <span>les</span> <span><span class=\"nc-orange\">éventrations</span></span>, les <span><span class=\"nc-orange\">hernies</span></span> et les <span><span class=\"nc-orange\">distensions abdominales</span></span>, puis précise les caractères de la <span>masse</span> : localisation sur un quadrant, taille, forme, contours, consistance, caractère mobile ou <span class=\"nc-green nc-bold\">fixe</span>, caractère <span class=\"nc-blue nc-bold\">indolore</span> ou douloureux, percussion et auscultation.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Masses abdominales selon la localisation</h4>\n      <table>\n        <thead><tr><th>Région</th><th>Causes principales</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-purple\">Hypochondre droit</span></td><td><span>Hépatomégalie</span> ; <span>lésion</span> de l’angle colique droit, du rein droit ou de la surrénale droite ; <strong><span class=\"nc-yellow_bg\">grosse </span><span><span class=\"nc-yellow_bg\">vésicule</span></span><span class=\"nc-yellow_bg\"> biliaire</span></strong> (<span class=\"nc-red nc-bold\">mobile avec la respiration</span>) : <span><span class=\"nc-red nc-bold\">tumeur maligne de la tête du pancréas</span></span>, <span class=\"nc-red nc-bold\">hydrocholécyste</span>, <span><span class=\"nc-red nc-bold\">cholécystite</span></span><span class=\"nc-red nc-bold\"> aiguë</span>, <span>cancer de la vésicule</span></td></tr>\n          <tr><td>Ép<span>iga</span>stre</td><td><span class=\"nc-blue_bg\">Hypertrophie du </span><span><span class=\"nc-blue_bg\">lobe gauche du foie</span></span> ; <span><span class=\"nc-orange_bg nc-bold\">tumeur gastrique</span></span> ; <span class=\"nc-blue_bg\">tumeur</span> de la queue du pancréas ; lésions du <span class=\"nc-purple nc-bold\">côlon transverse</span></td></tr>\n          <tr><td><span class=\"nc-blue\">Hypochondre gauche</span></td><td><strong><span><span class=\"nc-yellow_bg\">Splénomégalie</span></span><span class=\"nc-yellow_bg\"> homogène</span> :</strong> <span><span class=\"nc-orange_bg nc-bold\">hypertension</span></span><span class=\"nc-orange_bg nc-bold\"> portale</span>, infection, hémolyse, hémopathie ; <br><strong><span class=\"nc-yellow_bg\">Splénomégalie hétérogène</span> :</strong> <span>abcès</span>, kyste hydatique, <span class=\"nc-blue_bg\">tumeur</span> ; <br><strong>Autres origines :</strong> <span class=\"nc-blue_bg\">tumeur</span> de la <span class=\"nc-red nc-bold\">queue</span> du pancréas, grosse tubérosité gastrique, angle colique gauche, rein gauche</td></tr>\n          <tr><td>Flanc droit</td><td><span><span class=\"nc-brown_bg\">Lésion</span></span><span class=\"nc-brown_bg\"> rénale</span> (<span><span class=\"nc-blue_bg\">tumeur</span> maligne</span>, hydronéphrose) ; <span class=\"nc-brown_bg\">lésion surrénalienne</span> (<span class=\"nc-blue_bg\">tumeur</span> bénigne ou maligne) ; <span><span class=\"nc-blue_bg\">tumeur</span> rétropéritonéale primitive</span> (sarcome) ; <span class=\"nc-blue_bg\">lésions du psoas</span> (<span class=\"nc-blue_bg\">hématome</span>, <span><span class=\"nc-blue_bg\">abcès</span></span>, <span class=\"nc-blue_bg\">tumeur</span>) ; cancer du côlon (exceptionnellement palpé)</td></tr>\n          <tr><td>Flanc gauche</td><td><span><span class=\"nc-brown_bg\">Lésion</span></span><span class=\"nc-brown_bg\"> rénale</span> (<span><span class=\"nc-blue_bg\">tumeur</span> maligne</span>, hydronéphrose) ; <span class=\"nc-brown_bg\">lésion surrénalienne</span> (<span class=\"nc-blue_bg\">tumeur</span> bénigne ou maligne) ; <span><span class=\"nc-blue_bg\">tumeur</span> rétropéritonéale primitive</span> (sarcome) ; <span class=\"nc-blue_bg\">lésions du psoas</span> (<span class=\"nc-blue_bg\">hématome</span>, <span><span class=\"nc-blue_bg\">abcès</span></span>, <span class=\"nc-blue_bg\">tumeur</span>) ; cancer du côlon (exceptionnellement palpé)</td></tr>\n          <tr><td>Région ombilicale</td><td><span><span class=\"nc-pink_bg\">Anévrisme de l’aorte abdominale</span></span> ; cancer du <span class=\"nc-purple nc-bold\">côlon transverse</span> ; tumeurs du grêle ; <span class=\"nc-blue_bg\">tumeur</span> mésentérique</td></tr>\n          <tr><td>Fosse iliaque droite</td><td>Kyste de l’ovaire ; <span><span class=\"nc-blue_bg\">tumeur</span> du cæcum</span> ; <span><span class=\"nc-red_bg\">appendicite</span></span><span class=\"nc-red_bg\"> dans sa forme abcédée</span> ; <span><span class=\"nc-red_bg\">maladie de Crohn</span></span><span class=\"nc-red_bg\"> compliquée d’un </span><span><span class=\"nc-red_bg\">abcès</span></span></td></tr>\n          <tr><td>Hypogastre</td><td><strong>À éliminer en premier :</strong> <span class=\"nc-yellow_bg\">fécalome</span>, <span><span class=\"nc-yellow_bg\">grossesse</span></span>, <span class=\"nc-yellow_bg\">globe vésical</span> ; <br><strong>Causes utéro-ovariennes :</strong> <span class=\"nc-orange_bg\">fibrome utérin</span>, <span><span class=\"nc-orange_bg\">cancer de l’endomètre</span></span>, <span><span class=\"nc-orange_bg\">cancer de l’ovaire</span></span></td></tr>\n          <tr><td>Fosse iliaque gauche</td><td>Kyste de l’ovaire ; <span><span class=\"nc-blue_bg\">tumeur</span> sigmoïdienne</span> ; s<span>igm</span>oïdite avec <span>abcès</span> péri-sigmoïdien</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <strong>Masses ubiquitaires</strong> — observables dans diverses régions : <span>carcinose péritonéale</span>, <span>adénopathies</span>, <span class=\"nc-orange\">hernies</span> et <span class=\"nc-orange\">éventrations</span>, <span class=\"nc-blue_bg\">hématome</span> de paroi, lipome.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un bord hépatique palpable n’est pas à lui seul une hépatomégalie : tenir compte de la morphologie, de la position du diaphragme et confirmer le volume par imagerie si nécessaire.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"276-2","rang":"B","rubrique":"Etiologie","titre":"Connaître les principales causes d’hépatomégalie et de masse abdominale","contenu":"<div class=\"notion-course\"><p>L’<span>hépatomégalie</span> et <span>les</span> masses abdominales relèvent d’étiologies nombreuses, présentées ci-dessous en deux tableaux : les causes d’<span>hépatomégalie</span> classées par mécanisme, puis les masses abdominales palpables selon leur siège.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principales causes d’<span>hépatomégalie</span></h4>\n      <table>\n        <thead><tr><th>Catégorie / mécanisme</th><th>Pathologies</th></tr></thead>\n        <tbody>\n          <tr><td>Maladies hépatiques primitives, aiguës ou chroniques</td><td><span><span class=\"nc-orange_bg\">Stéatose</span> / stéato-hépatite</span> liée à l’<span><span class=\"nc-green\">alcool</span></span> ou métabolique ; <span><span class=\"nc-orange_bg\">cirrhose</span></span> (l’<span>hépatomégalie</span> y est inconstante) ; <span><span class=\"nc-purple\">hépatites</span></span> aiguës ou chroniques</td></tr>\n          <tr><td>Congestion par obstacle au retour veineux hépatique</td><td><span><span class=\"nc-orange_bg\">Insuffisance cardiaque droite</span></span>, péricardite <span>constrictive</span> ; <span>syndrome de Budd-Chiari</span> (exceptionnel)</td></tr>\n          <tr><td>Tumeurs hépatiques</td><td><strong>Malignes :</strong> primitives — <span><span class=\"nc-orange_bg nc-bold\">carcinome hépatocellulaire</span></span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> ; secondaires — <span><span class=\"nc-orange\">métastases</span></span> ; hémopathie maligne (très rare) ; <br><strong>Bénignes :</strong> polykystose hépatique ou hépatorénale ; autres tumeurs bénignes (<span>hépatomégalie</span> exceptionnelle)</td></tr>\n          <tr><td>Atteintes infectieuses</td><td><span>Abcès hépatique</span> amibien ou <span>bactérien</span> ; <span>lésion parasitaire</span> (hydatidose)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Masses abdominales palpables selon le siège</h4>\n      <table>\n        <thead><tr><th>Siège</th><th>Organe</th><th>Cause</th></tr></thead>\n        <tbody>\n          <tr><td>Ép<span>iga</span>stre</td><td>Estomac, pancréas, foie</td><td><span><span class=\"nc-orange_bg nc-bold\">Tumeur gastrique</span></span> ; tumeur ou pseudo-kyste pancréatique (rarement palpables) ; <span>hépatomégalie</span> aux dépens du foie gauche</td></tr>\n          <tr><td><span class=\"nc-purple\">Hypochondre droit</span></td><td>Foie, <span>vésicule</span> biliaire</td><td><span>Hépatomégalie</span> ; obstacle biliaire du bas cholédoque (ex. cancer de la tête du pancréas) ; <span><span class=\"nc-orange_bg\">tumeur maligne de la vésicule</span></span></td></tr>\n          <tr><td>Hypochondre et flanc gauches</td><td>Rate</td><td><span>Splénomégalie</span></td></tr>\n          <tr><td>Fosse iliaque droite</td><td>Cæcum, ovaire droit</td><td><span>Cancer du côlon droit</span> ; <span>maladie de Crohn</span> (iléite, <span><span class=\"nc-blue_bg\">abcès</span></span>) ; <span><span class=\"nc-blue_bg\">abcès</span></span> appendiculaire (rare) ; kyste ovarien ; <span><span class=\"nc-blue_bg\">tumeur</span> ovarienne</span></td></tr>\n          <tr><td>Fosse iliaque gauche</td><td>S<span>igm</span>oïde, ovaire gauche</td><td><span>Constipation</span> ; <span>tumeur du sigmoïde</span> ; s<span>igm</span>oïdite ; kyste ovarien ; <span>tumeur ovarienne</span></td></tr>\n          <tr><td>Région ombilicale</td><td>Aorte, <span class=\"nc-purple nc-bold\">côlon transverse</span>, grêle</td><td><span>Anévrysme de l’aorte abdominale</span> ; <span>cancer colique</span> ; <span class=\"nc-blue_bg\">tumeur</span> du grêle (rare)</td></tr>\n          <tr><td>Hypogastre</td><td>Utérus, vessie</td><td><span><span class=\"nc-yellow_bg\">Grossesse</span></span> ; <span class=\"nc-orange_bg nc-bold\">fibromyome utérin</span> ; <span><span class=\"nc-orange_bg\">cancer de l’endomètre</span></span> ; <span class=\"nc-yellow_bg\">globe vésical</span> ; <span><span class=\"nc-blue_bg\">tumeur</span> vésicale</span></td></tr>\n          <tr><td>Ubiquitaire</td><td>Péritoine, ganglions, paroi</td><td><span>Carcinose péritonéale</span> ; <span>adénopathies</span> (lymphome, métastases) ; <span class=\"nc-orange\">hernies</span> et <span class=\"nc-orange\">éventrations</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Hépatomégalie</span> selon le caractère focal ou non de l’imagerie</h4>\n      <table>\n        <thead><tr><th>Profil</th><th>Étiologie</th><th>Repères clinico-bio-radiologiques</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"6\"><strong>Sans <span>lésion</span> focale</strong></td><td><span><span class=\"nc-orange_bg\">Stéatose</span></span></td><td><span><span class=\"nc-green\">Alcool</span></span>, <span><span class=\"nc-orange\">syndrome métabolique</span></span> ; <span>parenchyme hépatique hyperéchogène</span></td></tr>\n          <tr><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span></td><td>FdR de <span class=\"nc-orange_bg\">cirrhose</span>, signes d’<span>IHC</span> et/ou d’<span><span class=\"nc-red nc-bold\">HTP</span></span> ; clinique : <span><span class=\"nc-red nc-bold\">foie dur à la palpation</span></span>, <span><span class=\"nc-red nc-bold\">HMG à bord tranchant</span></span> ; écho : <span>contours bosselés</span>, <span>hépatomégalie</span> <span class=\"nc-green\">diffuse</span> ou <span class=\"nc-green\">sectorielle</span>, parfois absente</td></tr>\n          <tr><td><span><span class=\"nc-orange\">Insuffisance cardiaque</span></span></td><td>FdR, cardiopathie connue, signes d’<span><span class=\"nc-orange\">insuffisance cardiaque</span></span> ; <span>veines hépatiques dilatées</span> à l’imagerie</td></tr>\n          <tr><td><span><span class=\"nc-orange_bg\">Cholestase chronique</span></span></td><td><span>Prurit</span>, <span>ictère</span> ; <span>dilatation des voies biliaires</span></td></tr>\n          <tr><td><span>Infiltration tumorale</span></td><td><span><span class=\"nc-red nc-bold\">Altération de l’état général</span></span> ; <span>hémopathies</span> (lymphome), <span>cancer du sein</span> (rare)</td></tr>\n          <tr><td><span>Syndrome de Budd-Chiari</span></td><td><span><span class=\"nc-blue_bg\">Ascite</span></span> ; <span><span class=\"nc-blue_bg\">veines hépatiques non visualisées</span></span><span class=\"nc-blue_bg\"> à l’imagerie</span></td></tr>\n          <tr><td rowspan=\"3\"><strong>Avec <span>lésion</span> focale</strong></td><td><span><span class=\"nc-blue_bg\">Tumeur</span> hépatique</span></td><td><strong>Bénigne :</strong> polykystose hépatique ou hépato-rénale (<span>les</span> autres tumeurs bénignes causent rarement une HMG) ; <strong>Maligne :</strong> <span><span class=\"nc-red_bg\">CHC</span></span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> ; <strong><span class=\"nc-red_bg\">Secondaire</span> :</strong> <span class=\"nc-red nc-bold\">contexte de cancer</span> connu, signes en lien avec le primitif</td></tr>\n          <tr><td><span>Abcès hépatique</span></td><td><span>Syndrome septique</span> → <span><span class=\"nc-purple_bg\">abcès</span></span><span class=\"nc-purple_bg\"> amibien ou </span><span><span class=\"nc-purple_bg\">bactérien</span></span></td></tr>\n          <tr><td><span>Parasitoses</span></td><td>Séjour en <span>zone d’endémie</span> (<span>hydatidose</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span> · 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 234 — <span><span class=\"nc-orange\">Insuffisance cardiaque</span></span> · 219 — Pathologie du fer · 275 — <span>Splénomégalie</span> · 308 — <span class=\"nc-blue_bg\">Tumeur</span> pancréas · 303 — <span class=\"nc-blue_bg\">Tumeur</span> estomac · 301 — <span class=\"nc-blue_bg\">Tumeur</span> colon - rectum · 306 — <span class=\"nc-blue_bg\">Tumeur</span> ovaire · 225 — Artériopathie oblitérante - anévrysme</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"276-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique devant une hépatomégalie et une masse abdominale","contenu":"<div class=\"notion-course\"><p>La démarche est <span>clinique d’abord</span> : la <span>palpation</span> caractérise la <span>masse</span> — <span>siège</span>, <span>taille</span>, <span>consistance</span>, <span>mobilité</span> — puis l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span> abdominale</span>, réalisée dans le prolongement de l’examen clinique, <span>confirme l’hépatomégalie</span>, écarte <span>les</span> autres <span>masses abdominales</span> et oriente l’étiologie.</p>\n      <p>Devant une <span>hépatomégalie</span>, l’<span>échographie</span> distingue <strong>trois profils</strong> qui commandent la suite des explorations.</p>\n      <table>\n        <thead><tr><th>Profil échographique</th><th>Orientation étiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span>Hépatomégalie</span> <span><span class=\"nc-green\">diffuse</span> et <span class=\"nc-green\">homogène</span></span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span>, <span><span class=\"nc-orange_bg\">stéatose</span> / stéato-hépatite</span>, <span><span class=\"nc-blue_bg\">foie cardiaque</span></span>, <span>hépatite aiguë ou chronique</span>, <span>hémochromatose</span>, <span><span class=\"nc-orange_bg\">cholestase chronique</span></span></td></tr>\n          <tr><td><span>Hépatomégalie</span> <span><span class=\"nc-green\">sectorielle</span> mais <span class=\"nc-green\">homogène</span></span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span> (diagnostic le plus fréquent) ; plus rarement, <span>hypertrophie compensatrice</span> répondant à l’atrophie d’un autre secteur (<span class=\"nc-orange\">obstruction</span> des voies biliaires, des veines hépatiques ou portes du secteur atrophié)</td></tr>\n          <tr><td><span><span class=\"nc-green_bg\">Hépatomégalie</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">hétérogène</span></span></td><td>Doit faire chercher une <span><span class=\"nc-red_bg nc-bold\">tumeur du foie</span></span>, traduite par des <span><span class=\"nc-blue nc-bold\">nodules</span></span> ou des <span><span class=\"nc-blue nc-bold\">plages de parenchyme anormal</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Toute <span><span class=\"nc-green_bg\">hépatomégalie hétérogène</span> doit faire chercher une <span class=\"nc-red_bg nc-bold\">tumeur du foie</span></span> jusqu’à preuve du contraire.</div>\n      <p>Lorsque la confrontation <span>clinique</span>, <span>biologique</span> et <span>radiologique</span> ne permet pas d’établir la cause, la <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span></span> est indiquée.</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"276-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","contenu":"<div class=\"notion-course\"><p>Devant une <span>hépatomégalie</span> ou une <span><span class=\"nc-blue nc-bold\">masse</span></span><span class=\"nc-blue nc-bold\"> abdominale</span>, l’<span>interrogatoire</span> et l’<span>examen physique</span> orientent fortement le diagnostic et conditionnent le choix des examens complémentaires.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Interrogatoire</h4>\n      <ul>\n        <li><strong>Circonstances de découverte :</strong> fortuite, <span>dépistage</span>, <span>douleur</span>, <span>ictère</span></li>\n        <li><strong>Date d’apparition et <span>évolution</span></strong> de la <span>masse</span></li>\n        <li><strong>Contexte :</strong> voyage en zone d’endémie</li>\n        <li><strong><span>Facteurs de risque</span> de <span>cirrhose</span> :</strong> consommation d’<span><span class=\"nc-green\">alcool</span></span>, <span><span class=\"nc-orange\">syndrome métabolique</span></span>, facteurs de risque d’<span>hépatite virale</span></li>\n        <li><strong>Antécédents :</strong> médicaux, chirurgicaux et gynécologiques ; <span>antécédents familiaux</span> de cancers</li>\n        <li><strong>Traitements :</strong> <span>les</span> <span><span class=\"nc-pink\">anticoagulants</span></span> favorisent la survenue d’un <span>hématome de la paroi abdominale</span> (faux aspect de <span><span class=\"nc-blue nc-bold\">masse</span></span><span class=\"nc-blue nc-bold\"> abdominale</span>)</li>\n        <li><strong>Signes associés :</strong> <span><span class=\"nc-blue nc-bold\">fièvre</span></span>, <span>sueurs</span>, <span>amaigrissement</span>, <span class=\"nc-blue nc-bold\">troubles du transit</span>, signes urinaires ou gynécologiques</li>\n        <li><strong>Date des dernières règles</strong> chez la femme non ménopausée</li>\n        <li><strong><span>Femme en âge de procréer :</span></strong> penser à la <span>grossesse extra-utérine</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examen physique</h4>\n      <ul>\n        <li>Caractériser la <span>masse</span> : localisation, taille, consistance, douleur spontanée ou provoquée, fixation aux plans profonds, caractère <span class=\"nc-blue\">pulsatile</span></li>\n        <li><span>Mobilité avec la respiration</span> : une <span>masse</span> de l’<span class=\"nc-purple\">hypochondre droit</span> ou de l’ép<span>iga</span>stre <span class=\"nc-red\">mobile</span> à la respiration est rattachée à une origine hépatique</li>\n        <li>Recherche d’un <span>syndrome septique</span> : <span><span class=\"nc-blue\">fièvre</span></span>, <span>frissons</span></li>\n        <li>Recherche d’un <span>syndrome de cholestase</span> : <span>ictère</span>, <span>prurit</span>, selles décolorées, urines foncées</li>\n        <li>Recherche de signes d’<span><span class=\"nc-orange_bg nc-bold\">insuffisance hépatocellulaire</span></span> et d’<span><span class=\"nc-orange_bg nc-bold\">hypertension portale</span></span></li>\n        <li>Recherche de <span><span class=\"nc-orange\">métastases</span></span> : palpation du foie et des aires ganglionnaires (<span>adénopathie de Troisier</span>), <span>nodules de carcinose</span>, <span class=\"nc-blue nc-bold\">touchers pelviens</span></li>\n        <li>Recherche de signes d’<span><span class=\"nc-orange_bg\">insuffisance cardiaque droite</span></span> — <span><span class=\"nc-green nc-bold\">reflux hépatojugulaire</span></span>, expansion systolique du <span class=\"nc-red nc-bold\">foie</span> — et d’une <span>ascite</span></li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractères sémiologiques de la <span>masse</span> à préciser</h4>\n      <table>\n        <thead><tr><th>Caractère</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Localisation</td><td>Rapportée à l’un des quadrants de l’abdomen</td></tr>\n          <tr><td>Taille et forme</td><td>Taille de la <span>masse</span> ; forme arrondie ou polylobée</td></tr>\n          <tr><td>Contours</td><td>Réguliers ou irréguliers, nets ou mal définis</td></tr>\n          <tr><td>Consistance</td><td>Rénitente, ferme ou dure ; homogène ou non</td></tr>\n          <tr><td>Mobilité</td><td><span class=\"nc-green nc-bold\">Mobile</span> ou fixe ; mobilité avec la respiration en faveur d’une origine hépatique</td></tr>\n          <tr><td>Sensibilité</td><td>Indolore ou douloureuse, spontanément ou à la palpation</td></tr>\n          <tr><td>Percussion</td><td>Sonorité ou matité</td></tr>\n          <tr><td>Auscultation</td><td>Recherche d’un souffle</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Signes orientant vers une hépatopathie</h4>\n      <table>\n        <thead><tr><th>Syndrome</th><th>Signes cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"nc-orange_bg nc-bold\">Insuffisance hépatocellulaire</span></td><td><span><span class=\"nc-orange nc-bold\">Ictère</span></span> conjonctival ou cutané ; <span>fœtor hepaticus</span> ; <span><span class=\"nc-green_bg nc-bold\">angiomes stellaires</span></span> ; <span><span class=\"nc-blue nc-bold\">érythrose palmaire</span></span> ; <span><span class=\"nc-blue nc-bold\">ongles</span> <span class=\"nc-blue nc-bold\">blancs</span></span> ; <span><span class=\"nc-orange nc-bold\">encéphalopathie hépatique</span></span> (<span>astérixis</span>, inversion du cycle nycthéméral) ; <span>hypogonadisme</span></td></tr>\n          <tr><td><span><span class=\"nc-orange_bg nc-bold\">Hypertension</span></span><span class=\"nc-orange_bg nc-bold\"> portale</span></td><td><span>Ascite</span> ; <span><span class=\"nc-blue nc-bold\">circulation veineuse collatérale</span></span> abdominale ; <span><span class=\"nc-orange_bg nc-bold\">splénomégalie</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ La palpation d’un <span><span class=\"nc-red nc-bold\">foie</span> <span class=\"nc-red nc-bold\">dur</span> à bord inférieur tranchant</span> est très évocatrice d’une <span><span class=\"nc-orange_bg\">cirrhose</span></span> ; on peut parfois percevoir des <span class=\"nc-green nc-bold\">nodules</span> à la surface du <span class=\"nc-red nc-bold\">foie</span>. Un <span class=\"nc-red nc-bold\">foie</span> normal est ferme.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"276-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les différents examens biologiques et radiologiques à réaliser en première intention devant une masse abdominale en fonction de l’étiologie suspectée","contenu":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-blue nc-bold\">masse abdominale</span></span>, l’examen complémentaire de référence est la <span><span class=\"nc-blue\">TDM</span> abdomino-pelvienne injectée</span>. Devant une <span>hépatomégalie</span>, l’exploration de <span>première intention</span> associe un bilan <span>biologique</span> simple et une <span><span class=\"nc-blue_bg nc-bold\">échographie</span> <span class=\"nc-blue_bg nc-bold\">abdominale</span></span>.</p>\n      <div class=\"callout callout-info\">📌 L’examen complémentaire de <strong><span>première intention</span> devant une <span><span class=\"nc-blue nc-bold\">masse</span></span><span class=\"nc-blue nc-bold\"> abdominale</span></strong> est la <span><span class=\"nc-blue\">TDM</span> abdomino-pelvienne injectée</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de <span>première intention</span> d’une <span>hépatomégalie</span></h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Clinique</td><td>Le <span class=\"nc-red nc-bold\">foie</span> palpable définit l’<span>hépatomégalie</span> en pratique (un <span class=\"nc-red nc-bold\">foie</span> palpable est le plus souvent pathologique) ; la mesure de la <span>flèche hépatique</span> (HMG si <span><span class=\"nc-red nc-bold\">&gt; 12 cm</span></span> sur la ligne médioclaviculaire) n’a plus d’intérêt clinique ; une <span>masse</span> de l’<span class=\"nc-purple\">hypochondre droit</span> ou de l’ép<span>iga</span>stre <span class=\"nc-red nc-bold\">mobile avec la respiration</span> est rattachée au <span class=\"nc-red nc-bold\">foie</span></td></tr>\n          <tr><td>Biologie</td><td><span><span class=\"nc-blue_bg\">NFS</span></span>, <span><span class=\"nc-blue_bg\">bilan hépatique</span></span>, <span>TP</span>, <span><span class=\"nc-blue_bg\">albumine</span></span> — à la recherche de signes d’<span><span class=\"nc-orange nc-bold\">insuffisance hépatique</span></span></td></tr>\n          <tr><td><span>Échographie <span class=\"nc-blue_bg nc-bold\">abdominale</span></span></td><td>Mesure l’<span>hépatomégalie</span>, écarte <span>les</span> diagnostics différentiels (autres masses abdominales) et oriente l’étiologie</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique de l’<span>échographie</span></h4>\n      <table>\n        <thead><tr><th>Signe échographique</th><th>Étiologie évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue\">Foie hyperéchogène</span></span></td><td><span><span class=\"nc-orange_bg\">Stéatose</span></span></td></tr>\n          <tr><td><span>Contours bosselés, <span class=\"nc-red nc-bold\">dysmorphie</span></span> (<span class=\"nc-blue nc-bold\">atrophie</span> du <span class=\"nc-purple nc-bold\">lobe droit</span>, <span class=\"nc-blue nc-bold\">hypertrophie</span> du <span class=\"nc-purple nc-bold\">lobe gauche</span>) avec signes d’<span><span class=\"nc-orange_bg nc-bold\">hypertension</span></span><span class=\"nc-orange_bg nc-bold\"> portale</span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span></td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Dilatation des veines hépatiques</span></span></td><td><span><span class=\"nc-orange_bg\">Insuffisance cardiaque droite</span></span></td></tr>\n          <tr><td><span>Dilatation des voies biliaires intra-hépatiques</span></td><td><span><span class=\"nc-orange_bg\">Cholestase</span></span><span class=\"nc-orange_bg\"> chronique</span></td></tr>\n          <tr><td><span>Nodule hétérogène</span> à <span class=\"nc-red nc-bold\">plages hyper et hypoéchogènes</span></td><td><span><span class=\"nc-orange_bg nc-bold\">Carcinome hépatocellulaire</span></span> (<span>nodule</span> suspect sur <span>cirrhose</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de seconde intention selon le contexte</h4>\n      <ul>\n        <li><strong>Absence de <span>lésion</span> focale :</strong> <span>sérologies</span> des <span><span class=\"nc-purple\">hépatites</span> virales</span>, <span>hépatite auto-immune</span>, bilan de <span>surcharge en fer</span> ; <span>élastométrie</span> et test sanguin de fibrose si <span>stéatose</span> ; <span>cholangio-IRM</span> ou <span>TDM</span> injectée si maladie biliaire suspectée</li>\n        <li><strong><span>Lésion</span> focale :</strong> <span><span class=\"nc-blue_bg\">TDM / IRM</span></span> ; <span><span class=\"nc-purple nc-bold\">sérologie des échinococcoses</span></span> si kyste hépatique ; <span><span class=\"nc-purple nc-bold\">hémocultures</span></span> et <span>sérologie <em>Entamoeba histolytica</em></span> si <span>abcès</span> hépatique</li>\n        <li><strong>Bilan non concluant :</strong> <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span></span> si clinique, biologie et imagerie ne permettent pas d’établir la cause</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span> · 278 — <span>Ictère</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":1},{"id":"276-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et contre-indications de la ponction et de la biopsie de foie","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span> (PBH)</span> est indiquée lorsque la clinique, la biologie et l’imagerie ne permettent pas d’établir la cause d’une <span>hépatomégalie</span>. Trois voies d’abord sont possibles, choisies selon le <span>terrain</span> et <span>les</span> <span>contre-indications</span>.</p>\n      <div class=\"callout callout-info\">📌 <strong>Indication :</strong> <span>démarche diagnostique non concluante</span> — la <span>PBH</span> est indiquée lorsque <span>clinique</span>, <span>biologie</span> et <span>imagerie</span> ne permettent pas d’établir la cause d’une <span>hépatomégalie</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Voies de prélèvement</h4>\n      <table>\n        <thead><tr><th>Voie</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span>Percutanée</span></td><td>Voie de <strong><span>première intention</span></strong> ; <span>guidage échographique</span> le plus souvent ; <span>anesthésie locale</span></td></tr>\n          <tr><td><span>Transjugulaire</span></td><td>Voie <span>transveineuse</span> ; <strong>moins de risque <span>hémorragique</span></strong> ; <span>anesthésie locale</span> ; <span>ne permet pas de biopsier une lésion focale</span></td></tr>\n          <tr><td><span>Chirurgicale</span></td><td>Réservée à des situations particulières</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Contre-indications</span></h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Contre-indications</th></tr></thead>\n        <tbody>\n          <tr><td>Voie percutanée (faire alors privilégier la voie transveineuse)</td><td><span><span class=\"nc-blue_bg\">Ascite</span>, même minime</span> ; <span>plaquettes &lt; <span>60 G/L</span></span> ; <span><span class=\"nc-red nc-bold\">TP &lt; </span><span><span class=\"nc-red nc-bold\">50 %</span></span></span> ; <span><span class=\"nc-red nc-bold\">TCA &gt; </span><span><span class=\"nc-red nc-bold\">1,5</span></span></span> ; <span class=\"nc-pink_bg\">hémodialyse</span> ; <span>antiagrégants plaquettaires</span>, <span><span class=\"nc-pink_bg\">anticoagulants</span></span>, <span><span class=\"nc-pink_bg\">AINS</span></span></td></tr>\n          <tr><td>Voie transveineuse</td><td><span>Thrombose des 3 veines sus-hépatiques</span></td></tr>\n          <tr><td>Dans tous <span>les</span> cas</td><td><span>Dilatation des voies biliaires intra-hépatiques</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Où prélever</h4>\n      <ul>\n        <li><strong><span>Hépatomégalie <span class=\"nc-green\">diffuse</span></span> :</strong> la <span>PBH</span> peut être faite <strong><span class=\"nc-red nc-bold\">en tout point</span></strong></li>\n        <li><strong><span><span class=\"nc-green_bg\">Hépatomégalie hétérogène</span></span> :</strong> prélèvement sur la <span>lésion focale</span> + <span><span class=\"nc-red nc-bold\">1 point</span></span><span class=\"nc-red nc-bold\"> du reste du parenchyme</span> (<span>2 prélèvements</span>)</li>\n        <li><strong><span>Abcès hépatique volumineux</span> :</strong> <span><span class=\"nc-blue nc-bold\">ponction ± drainage</span></span><span class=\"nc-blue nc-bold\"> sous </span><span><span class=\"nc-blue nc-bold\">contrôle échographique</span></span></li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Complications de la <span>PBH</span> :</strong> <span><span class=\"nc-red_bg\">douleurs abdominales</span></span> ; <span><span class=\"nc-red_bg\">effraction pleurale ou biliaire</span></span> ; <span><span class=\"nc-red_bg\">saignement</span></span> (<span><span class=\"nc-red_bg\">hématome</span></span>, <span><span class=\"nc-red_bg\">hémopéritoine</span></span>, <span><span class=\"nc-red_bg\">choc hémorragique</span></span>). Elles justifient une <span>surveillance FC/PA</span> et un <span>alitement</span> pendant <span>≥ 6 h</span>.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La biopsie hépatique n’est pas automatique devant toute hépatomégalie inexpliquée. Indication, voie et risque hémorragique dépendent du bilan ; ne pas ponctionner à l’aveugle une lésion vasculaire ou hydatique suspectée. L’<span class=\"nc-blue_bg\">ascite</span> et les antithrombotiques imposent une évaluation, pas une règle unique pour toute voie de biopsie.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"276-7","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de carcinome hépatocellulaire (CHC) typique chez un patient porteur d’une cirrhose","contenu":"<div class=\"notion-course\"><p>Chez un patient porteur d’une <span><span class=\"nc-orange_bg nc-bold\">cirrhose</span></span>, tout <span>nodule</span> est suspect : il s’intègre dans le <strong><span>dépistage</span> du <span><span class=\"nc-orange_bg nc-bold\">carcinome</span></span><span class=\"nc-orange_bg nc-bold\"> hépatocellulaire</span> (CHC)</strong> par <span>échographie</span> semestrielle. Un <span>nodule</span> détecté justifie une <span>imagerie en coupe injectée</span> (<span>TDM</span> ou <span>IRM</span>).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> du CHC typique</h4>\n      <table>\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span>nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td>Sans injection</td><td><span><span class=\"nc-blue_bg\">Nodule</span></span><span class=\"nc-blue_bg\"> </span><span><span class=\"nc-blue_bg\">iso ou hypodense</span></span></td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">artériel</span></span></td><td><span><span class=\"nc-blue_bg\">Hyperdensité</span></span> du <span>nodule</span> — <span><span class=\"nc-red nc-bold\">wash-in</span></span> (rehaussement intense)</td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">portal</span></span></td><td>Lavage du contraste, aspect <span>hypovasculaire</span> — <span><span class=\"nc-red nc-bold\">wash-out</span></span></td></tr>\n        </tbody>\n      </table>\n      <p>Le CHC présente typiquement une artérialisation de sa vascularisation. Tous les CHC ne montrent pas un rehaussement <span class=\"nc-red\">artériel</span> typique ; interpréter la cinétique complète et le terrain.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-chc-cirrhose.png\" alt=\"TDM abdomino-pelvienne, 4 coupes axiales aux temps sans injection, artériel, portal et tardif, montrant un nodule de carcinome hépatocellulaire spontanément hypodense, hyper-rehaussé au temps artériel puis présentant un lavage aux temps portal et tardif\" loading=\"lazy\">\n        <figcaption><span>TDM abdomino-pelvienne</span>, coupes axiales (4 temps). <span>Lésion</span> <span>hypodense spontanément</span> (1), <span>hyper-rehaussée au temps artériel</span> (2 — prise de contraste supérieure au parenchyme hépatique), présentant un <span>lavage aux temps portal et tardif</span> (3 — devenant hypodense par rapport au parenchyme) : aspect typique de <span>carcinome hépatocellulaire</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 Un <span>nodule</span> de <span><span class=\"nc-red nc-bold\">&gt; 1 cm</span></span> présentant <span><span class=\"nc-red nc-bold\">wash-in</span></span> et <span><span class=\"nc-red nc-bold\">wash-out</span></span>, développé sur une <span><span class=\"nc-red nc-bold\">cirrhose certaine</span></span> et validé en <strong><span>RCP</span></strong>, permet un diagnostic non invasif de <span class=\"nc-orange\">CHC</span>, sans <span>biopsie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/liver","label":"Radiopaedia : Liver"},{"href":"https://radiopaedia.org/cases/liver-segments-annotated-ct-1","label":"Radiopaedia : Liver segments annotated ct 1"},{"href":"http://radiopaedia.org","label":"radiopaedia.org"}]},{"id":"276-8","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de métastases hépatiques","contenu":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-blue_bg\">tumeur</span> hépatique solide</span> sans maladie chronique du foie documentée, l’analyse repose sur la <span>cinétique de prise du produit de contraste</span> en <span><span class=\"nc-blue\">échographie</span></span><span class=\"nc-blue\"> de contraste</span>, <span><span class=\"nc-blue\">TDM</span></span> ou <span><span class=\"nc-blue\">IRM</span></span>, et sur la recherche d’un <span><span class=\"nc-red nc-bold\">contexte de cancer</span> extra-hépatique</span> (sexe, âge, cancer connu).</p>\n      <p>Le <span>contexte d’un cancer extra-hépatique connu</span> pèse fortement en faveur du diagnostic de métastase. La <span>TEP-FDG</span> (ou <span>TEP</span>-choline), en cas de <span>lésion</span> hépatique isolée, aide au <span>diagnostic différentiel</span> entre <span>métastase</span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> et <span class=\"nc-blue_bg\">tumeur</span> bénigne.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> des <span class=\"nc-orange\">métastases</span> hépatiques</h4>\n      <table>\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span>nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td><span>Temps <span class=\"nc-red\">artériel</span></span></td><td><span>Absence de rehaussement</span> de la <span>lésion</span></td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">portal</span></span></td><td><span>Absence de rehaussement</span> de la <span>lésion</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-metastases-hepatiques.png\" alt=\"TDM abdomino-pelvienne, coupes axiales avec injection : à gauche métastases hépatiques classiques discrètement rehaussées au temps portal en périphérie mais restant hypodenses ; à droite métastases hyper-rehaussées au temps artériel plus que le parenchyme hépatique\" loading=\"lazy\">\n        <figcaption><span>TDM abdomino-pelvienne</span>, coupes axiales. <strong>Métastases « classiques »</strong> (temps portal, 2 patients distincts) : lésions <span>discrètement rehaussées de façon hétérogène, plutôt en périphérie, mais restant hypodenses</span> par rapport au parenchyme. <strong>Métastases hyper-rehaussées</strong> (temps artériel) : <span>lésions rehaussées plus que le parenchyme hépatique</span> — cas particuliers du <span>cancer du rein, de la thyroïde, mélanome, tumeur neuro-endocrine</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">📌 Une <span>lésion</span> hépatique <span>sans rehaussement aux temps <span class=\"nc-red\">artériel</span> et <span class=\"nc-red\">portal</span></span> oriente vers une <span><span class=\"nc-orange\">métastase</span></span> ou un <span class=\"nc-orange\">adénome hépatocellulaire</span> ; le <span>contexte oncologique</span> (cancer extra-hépatique connu) tranche.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0},{"id":"276-9","rang":"B","rubrique":"Contenu multimédia","titre":"Tomodensitométrie de kyste hépatique typique","contenu":"<div class=\"notion-course\"><p>Devant une <span>lésion hépatique kystique</span> sans maladie chronique du foie, l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span></span> détermine si la <span>lésion</span> est un <strong><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></strong>. <span>Les</span> principales tumeurs kystiques à connaître sont : le <span class=\"nc-orange nc-bold\">kyste biliaire simple</span>, les kystes parasitaires (<span>hydatidose</span>, échinococcose alvéolaire), les <span>abcès</span> amibiens, les <span>abcès</span> à pyogènes et les tumeurs nécrosées.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Critères échographiques du <span class=\"nc-orange nc-bold\">kyste biliaire simple</span></h4>\n      <ul>\n        <li><span>Lésion</span> <span>parfaitement liquidienne</span> (anéchogène, avec renforcement postérieur)</li>\n        <li><span><span class=\"nc-red nc-bold\">Absence de toute paroi ou cloison interne</span></span></li>\n      </ul>\n      <p>Si l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span></span> confirme ces critères, le diagnostic de <span><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></span> est établi. On réalise néanmoins des <span><span class=\"nc-purple\">tests sérologiques d’hydatidose</span></span> chez <span>les</span> sujets ayant vécu en zone d’endémie au <span>contact</span> de chiens.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> du <span class=\"nc-orange nc-bold\">kyste biliaire simple</span> typique</h4>\n      <table>\n        <thead><tr><th>Critère</th><th>Aspect typique</th></tr></thead>\n        <tbody>\n          <tr><td>Forme</td><td><span>Lésion</span> <span>arrondie, à contours nets</span></td></tr>\n          <tr><td>Densité spontanée</td><td><span>Densité hydrique</span> homogène</td></tr>\n          <tr><td>Paroi</td><td><span>Paroi fine, voire invisible</span> ; pas de cloison interne</td></tr>\n          <tr><td>Après injection</td><td><span>Aucun rehaussement</span> (ni de la <span>lésion</span>, ni d’une paroi)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/276/tdm-kyste-hepatique.png\" alt=\"TDM abdomino-pelvienne, coupes axiales sans injection puis avec injection au temps portal, montrant à la pointe du foie droit une formation bien limitée à bords nets, sphérique, homogène, hypodense de densité liquidienne, sans cloison ni paroi et sans rehaussement\" loading=\"lazy\">\n        <figcaption><span>TDM abdomino-pelvienne</span>, coupes axiales (sans injection puis temps portal). <span>Formation bien limitée, à bords nets, sphérique ou ovale, homogène</span>, <span>hypodense de densité liquidienne, sans cloison ni paroi, sans rehaussement</span> après injection (pointe du foie droit, flèches grises) : aspect typique de <span>kyste hépatique simple</span>. Source : banque imagerie « Imagerie à connaître » (item 276).</figcaption>\n      </figure>\n      <p>Si l’<span>échographie</span> ne répond pas aux critères du kyste simple, la <span>lésion</span> est précisée par <span><span class=\"nc-blue\">TDM</span>, <span class=\"nc-blue\">IRM</span> ou <span class=\"nc-blue\">échographie de contraste</span></span> : il peut alors s’agir d’une <span class=\"nc-blue_bg\">tumeur</span> bénigne à potentiel malin, d’une <span><span class=\"nc-blue_bg\">tumeur</span> maligne</span>, d’un <span>kyste hydatique</span> ou d’un <span class=\"nc-orange nc-bold\">kyste biliaire simple</span> modifié par une hémorragie intrakystique.</p>\n      <div class=\"callout callout-info\">📌 Le <span><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></span> est un diagnostic d’imagerie : <span>lésion</span> <span>parfaitement liquidienne</span>, <span>sans paroi ni cloison</span>, <span>sans rehaussement</span>. Toute paroi épaisse, cloison interne, composante tissulaire ou rehaussement doit remettre en cause le diagnostic et faire évoquer un <span>kyste hydatique</span>, une <span><span class=\"nc-blue_bg\">tumeur</span> kystique</span> (bénigne à potentiel malin ou maligne) ou un <span><span class=\"nc-blue_bg\">abcès</span></span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un kyste simple typique ne justifie pas systématiquement une sérologie hydatique ; rechercher une exposition et des signes atypiques. Éviter toute ponction avant caractérisation si une hydatidose est possible.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"principes":"<p>Repères de conduite à tenir, reliés aux objectifs détaillés :</p><ul><li><strong>Connaître la démarche diagnostique devant une hépatomégalie et une masse abdominale</strong> — La démarche est clinique d’abord : la palpation caractérise la masse — siège, taille, consistance, mobilité — puis l’échographie abdominale, réalisée dans le prolongement de l’examen clinique, confirme l’hépatomégalie, écarte les autres masses abdominales et oriente l’étiologie.\n      Devant une hépatomégalie, l’échographie distingue trois profils qui commandent la suite des explorations.\n      \n        Profil échographiqueOrientation étiologique\n        \n          Hépatomégalie diffuse et homogèneCirrhose, stéatose / stéato-hépatite, foie cardiaque, hépatite aiguë ou chronique, hémochromatose, cholestase chronique\n          Hépatomégalie sectorielle mais homogèneCirrhose (diagnostic le plus fréquent) ; plus rarement, hypertrophie compensatrice répondant à l’atrophie d’un autre secteur (obstruction des voies biliaires, des veines hépatiques ou portes du secteur atrophié)\n          Hépatomégalie hétérogèneDoit faire chercher une tumeur du foie, traduite par des nodules ou des plages de parenchyme anormal\n        \n      \n      ⚠️ Toute hépatomégalie hétérogène doit faire chercher une tumeur du foie jusqu’à preuve du contraire.\n      Lorsque la confrontation clinique, biologique et radiologique ne permet pas d’établir la cause, la ponction-biopsie hépatique est indiquée..</li><li><strong>Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale</strong> — Devant une hépatomégalie ou une masse abdominale, l’interrogatoire et l’examen physique orientent fortement le diagnostic et conditionnent le choix des examens complémentaires.\n      Interrogatoire\n      \n        Circonstances de découverte : fortuite, dépistage, douleur, ictère\n        Date d’apparition et évolution de la masse\n        Contexte : voyage en zone d’endémie\n        Facteurs de risque de cirrhose : consommation d’alcool, syndrome métabolique, facteurs de risque d’hépatite virale\n        Antécédents : médicaux, chirurgicaux et gynécologiques ; antécédents familiaux de cancers\n        Traitements : les anticoagulants favorisent la survenue d’un hématome de la paroi abdominale (faux aspect de masse abdominale)\n        Signes associés : fièvre, sueurs, amaigrissement, troubles du transit, signes urinaires ou gynécologiques\n        Date des dernières règles chez la femme non ménopausée\n        Femme en âge de procréer : penser à la grossesse extra-utérine\n      \n      Examen physique\n      \n        Caractériser la masse : localisation, taille, consistance, douleur spontanée ou provoquée, fixation aux plans profonds, caractère pulsatile\n        Mobilité avec la respiration : une masse de l’hypochondre droit ou de l’épigastre mobile à la respiration est rattachée à une origine hépatique\n        Recherche d’un syndrome septique : fièvre, frissons\n        Recherche d’un syndrome de cholestase : ictère, prurit, selles décolorées, urines foncées\n        Recherche de signes d’insuffisance hépatocellulaire et d’hypertension portale\n        Recherche de métastases : palpation du foie et des aires ganglionnaires (adénopathie de Troisier), nodules de carcinose, touchers pelviens\n        Recherche de signes d’insuffisance cardiaque droite — reflux hépatojugulaire, expansion systolique du foie — et d’une ascite\n      \n      Caractères sémiologiques de la masse à préciser\n      \n        CaractèreModalités\n        \n          LocalisationRapportée à l’un des quadrants de l’abdomen\n          Taille et formeTaille de la masse ; forme arrondie ou polylobée\n          ContoursRéguliers ou irréguliers, nets ou mal définis\n          ConsistanceRénitente, ferme ou dure ; homogène ou non\n          MobilitéMobile ou fixe ; mobilité avec la respiration en faveur d’une origine hépatique\n          SensibilitéIndolore ou douloureuse, spontanément ou à la palpation\n          PercussionSonorité ou matité\n          AuscultationRecherche d’un souffle\n        \n      \n      Signes orientant vers une hépatopathie\n      \n        SyndromeSignes cliniques\n        \n          Insuffisance hépatocellulaireIctère conjonctival ou cutané ; fœtor hepaticus ; angiomes stellaires ; érythrose palmaire ; ongles blancs ; encéphalopathie hépatique (astérixis, inversion du cycle nycthéméral) ; hypogonadisme\n          Hypertension portaleAscite ; circulation veineuse collatérale abdominale ; splénomégalie\n        \n      \n      ⚠️ La palpation d’un foie dur à bord inférieur tranchant est très évocatrice d’une cirrhose ; on peut parfois percevoir des nodules à la surface du foie.</li></ul>"},"liensGlobaux":[{"href":"https://www.fmcgastro.org/postu-main/archives/postu-2012-paris/textes-postu-2012-paris/diagnostic-des-nodules-sur-cirrhose-quelle-est-la-place-de-la-biopsie%E2%80%88/","label":"Diagnostic des nodules sur cirrhose. Quelle est la place de la biopsie ? – FMC-HGE"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hépatomégalie confirmée — Foie palpable (> 12 cm en ligne médioclaviculaire). Échographie en 1re intention : diffuse/sectorielle, homogène ou hétérogène","detail":"<h4>CAT — <span class=\"kw-clinique\">hépatomégalie</span> : démarche diagnostique — Caractérisation échographique → orientation étiologique</h4>","branches":[{"to":"q-homogene","label":"Échostructure homogène (diffuse ou sectorielle)","color":"blue"},{"to":"q-mcf","label":"Échostructure hétérogène (nodules / plages anormales)","color":"amber"}]},{"id":"q-homogene","kind":"decision","label":"Hépatomégalie homogène : orientation étiologique ? — Clinique + biologie + échographie ± doppler","branches":[{"to":"t-steatose","label":"Foie hyperéchogène · alcool ou syndrome métabolique","color":"amber"},{"to":"t-cirrhose","label":"Contours bosselés · dysmorphie · foie dur à bord tranchant","color":"amber"},{"to":"t-cardiaque","label":"Veines hépatiques et VCI dilatées · insuffisance cardiaque droite","color":"amber"}]},{"id":"t-steatose","kind":"terminal","label":"Stéatose / stéatohépatite","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Consommation excessive d’alcool</span> ou <span class=\"kw-etio\">syndrome métabolique</span></li><li>Tour de taille <span class=\"kw-chiffre\">&gt; 102 cm</span> (homme) / <span class=\"kw-chiffre\">&gt; 88 cm</span> (femme)</li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Foie hyperéchogène</span> (« foie brillant »)</li></ul><h4>Biologie</h4><ul><li>Élévation modérée des <span class=\"kw-bio\">transaminases</span> et de la <span class=\"kw-bio\">γ-GT</span></li></ul><h4><span class=\"kw-chiffre\">2e intention</span></h4><ul><li>Évaluation de la <span class=\"kw-bio\">fibrose hépatique</span> : <span class=\"kw-imagerie\">élastométrie</span> et/ou test sanguin de fibrose</li></ul>"},{"id":"t-cirrhose","kind":"terminal","label":"Cirrhose","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Foie dur</span> à <span class=\"kw-clinique\">bord inférieur tranchant</span>, surface parfois nodulaire</li><li>Signes d’<span class=\"kw-clinique\">insuffisance hépatocellulaire</span> : <span class=\"kw-clinique\">ictère</span>, angiomes stellaires, érythrose palmaire, ongles blancs, encéphalopathie</li><li>Signes d’<span class=\"kw-clinique\">hypertension portale</span> : <span class=\"kw-clinique\">ascite</span>, circulation veineuse collatérale, <span class=\"kw-clinique\">splénomégalie</span></li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Contours irréguliers / bosselés</span>, <span class=\"kw-radio\">dysmorphie</span> (atrophie du lobe droit, hypertrophie du lobe gauche)</li><li>Signes d’<span class=\"kw-clinique\">HTP</span> : <span class=\"kw-radio\">splénomégalie</span>, voies de dérivation, flux porte inversé au doppler</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">↓ TP</span>, <span class=\"kw-bio\">↓ facteur V</span>, <span class=\"kw-bio\">↑ INR</span>, <span class=\"kw-bio\">↓ albumine</span>, <span class=\"kw-bio\">↑ bilirubine</span> ; thrombopénie (hypersplénisme)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Dépistage</span> du <span class=\"kw-etio\">CHC</span> : <span class=\"kw-imagerie\">échographie</span> + <span class=\"kw-bio\">AFP</span> tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">6 mois</span></li></ul><h4>Renvoi</h4><ul><li>Item 279 — Cirrhose</li></ul>"},{"id":"t-cardiaque","kind":"terminal","label":"Foie cardiaque","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Insuffisance cardiaque droite</span>, <span class=\"kw-etio\">péricardite constrictive</span> (exceptionnel : <span class=\"kw-etio\">syndrome de Budd-Chiari</span>)</li></ul><h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Reflux hépatojugulaire</span>, expansion systolique du foie, signes d’<span class=\"kw-ci\">insuffisance cardiaque</span> droite</li></ul><h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Dilatation des veines hépatiques</span> et de la <span class=\"kw-radio\">VCI</span></li></ul><h4>CAT</h4><ul><li><span class=\"kw-imagerie\">Échographie cardiaque (ETT)</span> devant une dilatation des veines hépatiques + VCI</li></ul>"},{"id":"q-mcf","kind":"decision","label":"Existe-t-il une maladie chronique du foie documentée ? — ATCD, facteurs de risque, clinique, biologie, échographie (± biopsie en foie non tumoral)","branches":[{"to":"q-mcf-type","label":"Oui — maladie chronique du foie (cirrhose +++)","color":"red"},{"to":"q-nature","label":"Non — pas de maladie chronique du foie","color":"blue"}]},{"id":"q-mcf-type","kind":"decision","label":"Quel diagnostic écarter en priorité ? — Toute image nodulaire sur cirrhose = CHC jusqu’à preuve du contraire","branches":[{"to":"t-chc","label":"Nodule > 1 cm · wash-in artériel + wash-out portal/tardif","color":"red"},{"to":"t-cholangio","label":"Dilatation des voies biliaires intra-hépatiques","color":"red"}]},{"id":"t-chc","kind":"terminal","label":"Carcinome hépatocellulaire (CHC)","color":"red","detail":"<h4><span class=\"kw-def\">Terrain</span></h4><ul><li>Survient sur <span class=\"kw-etio\">cirrhose</span> (<span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">1 à 5 %/an</span>) — diagnostic le plus fréquent d’une <span class=\"kw-clinique\">lésion</span> hétérogène sur foie chronique</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Nodule hétérogène</span> &gt; <span class=\"kw-chiffre\">1 cm</span>, plages hyper- et hypoéchogènes à l’<span class=\"kw-imagerie\">échographie</span></li><li><span class=\"kw-imagerie\">TDM/IRM injectées</span> : <span class=\"kw-radio\">wash-in</span> (hyperdensité artérielle) puis <span class=\"kw-radio\">wash-out</span> (lavage au temps portal/tardif)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">AFP</span> &gt; <span class=\"kw-chiffre\">400 ng/mL</span> : valeur diagnostique chez le cirrhotique (mais non suffisante)</li></ul><h4><span class=\"kw-ttt\">Biopsie</span></h4><ul><li><span class=\"kw-ttt\">Biopsie</span> écho-guidée + biopsie en foie normal si l’imagerie n’est pas caractéristique ; non indispensable si <span class=\"kw-clinique\">nodule</span> &gt;<span class=\"kw-chiffre\"> 1 cm</span> avec wash-in/wash-out sur cirrhose certaine validé en <span class=\"kw-ttt\">RCP</span></li></ul><h4>Renvoi</h4><ul><li>Item 304 — Tumeur du foie · Item 279 — Cirrhose</li></ul>"},{"id":"t-cholangio","kind":"terminal","label":"Cholangiocarcinome","color":"red","detail":"<h4>Orientation</h4><ul><li>Plus rare que le CHC ; suspecté devant une <span class=\"kw-radio\">dilatation des voies biliaires intra-hépatiques</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Cholangio-IRM</span> pour préciser l’obstacle biliaire ; <span class=\"kw-imagerie\">TDM/IRM triphasiques</span></li></ul><h4>Renvoi</h4><ul><li>Item 304 — Tumeur du foie</li></ul>"},{"id":"q-nature","kind":"decision","label":"Lésion kystique ou solide à l’échographie ? — L’échographie tranche entre contenu liquidien et tissulaire","branches":[{"to":"q-kystique","label":"Lésion kystique (liquidienne)","color":"blue"},{"to":"t-solide","label":"Lésion solide (même partiellement liquidienne)","color":"amber"}]},{"id":"q-kystique","kind":"decision","label":"Caractéristiques de la lésion kystique ? — Rechercher paroi, cloison, contexte septique, exposition parasitaire","branches":[{"to":"t-kyste-simple","label":"Parfaitement liquidienne, sans paroi ni cloison","color":"green"},{"to":"t-hydatique","label":"Paroi / cloison · séjour en zone d’endémie","color":"amber"},{"to":"t-abces","label":"Contexte septique fébrile · paroi épaisse","color":"red"}]},{"id":"t-kyste-simple","kind":"terminal","label":"Kyste biliaire simple","color":"green","detail":"<h4><span class=\"kw-imagerie\">Échographie</span></h4><ul><li><span class=\"kw-radio\">Lésion parfaitement liquidienne</span>, <span class=\"kw-radio\">anéchogène</span>, <span class=\"kw-radio\">sans paroi ni cloison</span>, <span class=\"kw-radio\">sans rehaussement</span></li></ul><h4>CAT</h4><ul><li>Diagnostic d’imagerie ; réaliser une <span class=\"kw-bio\">sérologie hydatidose</span> chez <span class=\"kw-clinique\">les</span> sujets ayant vécu en zone d’endémie</li></ul><h4>Alerte</h4><ul><li>Toute <span class=\"kw-alerte\">paroi épaisse</span>, <span class=\"kw-alerte\">cloison</span> ou <span class=\"kw-alerte\">composante tissulaire</span> remet en cause le diagnostic</li></ul>"},{"id":"t-hydatique","kind":"terminal","label":"Kyste hydatique","color":"amber","detail":"<h4>Contexte</h4><ul><li><span class=\"kw-etio\">Séjour en zone d’endémie</span>, <span class=\"kw-def\">contact</span> avec des chiens (<span class=\"kw-etio\">hydatidose</span> / échinococcose)</li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Kyste à paroi propre, cloisons internes / vésicules filles</span> ; précision par <span class=\"kw-imagerie\">TDM ou IRM</span></li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Sérologie des échinococcoses</span></li></ul>"},{"id":"t-abces","kind":"terminal","label":"Abcès hépatique","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Syndrome septique</span> (<span class=\"kw-clinique\">fièvre</span>, frissons) ; <span class=\"kw-clinique\">abcès</span> <span class=\"kw-etio\">amibien</span> ou <span class=\"kw-etio\">bactérien</span></li></ul><h4>Imagerie</h4><ul><li><span class=\"kw-radio\">Réhaussement périphérique au temps artériel, centre non réhaussé</span> (= <span class=\"kw-clinique\">abcès</span> ou tumeur nécrosée)</li></ul><h4>Biologie</h4><ul><li><span class=\"kw-bio\">Hémocultures</span>, <span class=\"kw-bio\">sérologie Entamoeba histolytica</span></li></ul><h4>CAT</h4><ul><li>Si <span class=\"kw-clinique\">abcès</span> volumineux : <span class=\"kw-ttt\">ponction ± drainage sous contrôle échographique</span></li></ul>"},{"id":"t-solide","kind":"terminal","label":"Tumeur solide : métastase / hémangiome","color":"amber","detail":"<h4>Démarche</h4><ul><li>Chercher un <span class=\"kw-etio\">contexte de cancer extra-hépatique</span> ; préciser la <span class=\"kw-radio\">cinétique de prise de contraste</span> (<span class=\"kw-imagerie\">échographie</span> de contraste, <span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM</span> triphasiques)</li></ul><h4>Hémangiome (bénin)</h4><ul><li><span class=\"kw-radio\">Réhaussement en mottes périphériques, progressif de la périphérie vers le centre</span> ; très hyperintense et homogène en <span class=\"kw-imagerie\">IRM T2</span></li></ul><h4>Métastase / adénome</h4><ul><li><span class=\"kw-radio\">Absence de réhaussement aux temps artériel et portal</span> ; la notion de <span class=\"kw-etio\">cancer extra-hépatique</span> pèse fortement</li></ul><h4>Piège</h4><ul><li>Un <span class=\"kw-radio\">réhaussement net au temps artériel avec wash-out</span> doit faire évoquer un <span class=\"kw-etio\">CHC</span> ; une <span class=\"kw-ttt\">ponction-biopsie</span> peut être indiquée</li></ul>"}]},"cards":[{"i":"04388e6f8602","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quelle est la définition d'une masse abdominale ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-blue nc-bold\">masse abdominale</span> se définit comme une <strong><span class=\"nc-red\">augmentation de volume</span></strong> d’un organe ou d’une région de l’abdomen.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un bord hépatique palpable n’est pas à lui seul une hépatomégalie : tenir compte de la morphologie, de la position du diaphragme et confirmer le volume par imagerie si nécessaire.</li></ul></div></div>"},{"i":"7f0cf3535529","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quelles sont les premières entités à éliminer devant la découverte d'une masse abdominale lors de l'examen clinique ?","a":"<div class=\"notion-course\"><p>Il convient d'éliminer en premier lieu les <ul><li><strong><span class=\"nc-orange\">éventrations</span></strong></li><li>les <strong>hernies</strong></li><li>les <strong><span class=\"nc-orange\">distensions abdominales</span></strong></li></ul></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un bord hépatique palpable n’est pas à lui seul une hépatomégalie : tenir compte de la morphologie, de la position du diaphragme et confirmer le volume par imagerie si nécessaire.</li></ul></div></div>"},{"i":"eafa09af18ca","n":276,"o":"276-1","u":"Définition","t":"Connaître la définition d’une masse abdominale","q":"Quels sont les différents caractères à analyser lors de l'examen clinique d'une masse abdominale ?","a":"<div class=\"notion-course\"><p>L'examen clinique d'une <span class=\"nc-blue nc-bold\">masse abdominale</span> doit préciser :</p><ul><li>sa <strong>localisation</strong> sur un quadrant</li><li>sa <strong>taille</strong>, sa <strong>forme</strong>, ses <strong>contours</strong></li><li>sa <strong>consistance</strong></li><li>son caractère <strong><span class=\"nc-green nc-bold\">mobile</span> ou <span class=\"nc-green nc-bold\">fixe</span></strong></li><li>son caractère <strong><span class=\"nc-blue nc-bold\">indolore</span> ou douloureux</strong></li><li>les findings à la <strong>percussion</strong> et à l'<strong>auscultation</strong></li></ul><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un bord hépatique palpable n’est pas à lui seul une hépatomégalie : tenir compte de la morphologie, de la position du diaphragme et confirmer le volume par imagerie si nécessaire.</li></ul></div></div>"},{"i":"6639130bb39a","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Comment caractériser une masse abdominale à l'examen physique ?","a":"<div class=\"notion-course\"><p>La caractérisation d'une <span class=\"nc-blue nc-bold\">masse abdominale</span> à l'examen physique comprend :</p><ul><li>Sa <strong>localisation</strong> par rapport aux quadrants abdominaux.</li><li>Sa <strong>taille et sa forme</strong> (arrondie, polylobée).</li><li>Ses <strong>contours</strong> (réguliers, irréguliers, nets, mal définis).</li><li>Sa <strong>consistance</strong> (rénitente, ferme, dure, homogène, non homogène).</li><li>Sa <strong>mobilité</strong> (<span class=\"nc-green nc-bold\">mobile</span>, fixe, mobilité avec la respiration - en faveur d'une origine hépatique).</li><li>Sa <strong>sensibilité</strong> (indolore, douloureuse, spontanément ou à la palpation).</li><li>La <strong>percussion</strong> (sonorité ou matité).</li><li>L'<strong>auscultation</strong> (recherche d'un souffle).</li></ul></div>"},{"i":"bcbbd1914a71","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Quels sont les éléments clés à rechercher lors de l'interrogatoire devant une hépatomégalie ou une masse abdominale pour orienter le diagnostic ?","a":"<div class=\"notion-course\"><p>Lors de l'interrogatoire, il faut rechercher :</p><ul><li>Les <strong>circonstances de découverte</strong> (fortuite, douleur, ictère, dépistage).</li><li>La <strong>date d'apparition et l'évolution</strong> de la masse.</li><li>Le <strong>contexte</strong> (voyage en zone d'endémie, facteurs de risque de cirrhose ou d'hépatite virale).</li><li>Les <strong>antécédents</strong> (médicaux, chirurgicaux, gynécologiques, familiaux de cancers).</li><li>Les <strong>traitements en cours</strong> (notamment les anticoagulants).</li><li>Les <strong>signes associés</strong> (<span class=\"nc-blue nc-bold\">fièvre</span>, sueurs, amaigrissement, <span class=\"nc-blue nc-bold\">troubles du transit</span>, signes urinaires ou gynécologiques).</li><li>La <strong>date des dernières règles</strong> chez la femme non ménopausée pour évoquer une éventuelle grossesse extra-utérine.</li></ul></div>"},{"i":"cc2523cc76a6","n":276,"o":"276-4","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen physique aidant au diagnostic d’hépatomégalie et de masse abdominale","q":"Quels sont les signes cliniques orientant vers une hépatopathie spécifiques à rechercher à l'examen physique en cas d'hépatomégalie ?","a":"<div class=\"notion-course\"><p>À l'examen physique, il faut rechercher les signes suivants :</p><ul><li>Signes de <strong>syndrome septique</strong> (<span class=\"nc-blue\">fièvre</span>, frissons).</li><li>Signes de <strong>cholestase</strong> (ictère, prurit, selles décolorées, urines foncées).</li><li>Signes d'<strong><span class=\"nc-orange_bg nc-bold\">insuffisance hépatocellulaire</span></strong> (<span class=\"nc-orange nc-bold\">ictère</span> conjonctival ou cutané, fœtor hepaticus, <span class=\"nc-green_bg nc-bold\">angiomes stellaires</span>, <span class=\"nc-blue nc-bold\">érythrose palmaire</span>, <span class=\"nc-blue nc-bold\">ongles</span> <span class=\"nc-blue nc-bold\">blancs</span>, <span class=\"nc-orange nc-bold\">encéphalopathie hépatique</span> avec astérixis, inversion du cycle nycthéméral, hypogonadisme).</li><li>Signes d'<strong><span class=\"nc-orange_bg nc-bold\">hypertension portale</span></strong> (ascite, <span class=\"nc-blue nc-bold\">circulation veineuse collatérale</span> abdominale, <span class=\"nc-orange_bg nc-bold\">splénomégalie</span>). La palpation d'un <strong>foie <span class=\"nc-red nc-bold\">dur</span> à bord inférieur tranchant</strong> est très évocatrice d'une <span class=\"nc-orange_bg\">cirrhose</span>.</li><li>Signes de <strong><span class=\"nc-orange\">métastases</span></strong> (palpation du foie, aires ganglionnaires comme l'adénopathie de Troisier, nodules de carcinose, <span class=\"nc-blue nc-bold\">touchers pelviens</span>).</li><li>Signes d'<strong><span class=\"nc-orange_bg\">insuffisance cardiaque droite</span></strong> (<span class=\"nc-green nc-bold\">reflux hépatojugulaire</span>, expansion systolique du <span class=\"nc-red nc-bold\">foie</span>, ascite).</li></ul></div>"},{"i":"73c848246881","n":276,"o":"276-2","u":"Etiologie","t":"Connaître les principales causes d’hépatomégalie et de masse abdominale","q":"Quels sont les points essentiels concernant les principales causes d’hépatomégalie et de masse abdominale ?","a":"<div class=\"notion-course\"><p>L’<span>hépatomégalie</span> et <span>les</span> masses abdominales relèvent d’étiologies nombreuses, présentées ci-dessous en deux tableaux : les causes d’<span>hépatomégalie</span> classées par mécanisme, puis les masses abdominales palpables selon leur siège.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principales causes d’<span>hépatomégalie</span></h4>\n      <table>\n        <thead><tr><th>Catégorie / mécanisme</th><th>Pathologies</th></tr></thead>\n        <tbody>\n          <tr><td>Maladies hépatiques primitives, aiguës ou chroniques</td><td><span><span class=\"nc-orange_bg\">Stéatose</span> / stéato-hépatite</span> liée à l’<span><span class=\"nc-green\">alcool</span></span> ou métabolique ; <span><span class=\"nc-orange_bg\">cirrhose</span></span> (l’<span>hépatomégalie</span> y est inconstante) ; <span><span class=\"nc-purple\">hépatites</span></span> aiguës ou chroniques</td></tr>\n          <tr><td>Congestion par obstacle au retour veineux hépatique</td><td><span><span class=\"nc-orange_bg\">Insuffisance cardiaque droite</span></span>, péricardite <span>constrictive</span> ; <span>syndrome de Budd-Chiari</span> (exceptionnel)</td></tr>\n          <tr><td>Tumeurs hépatiques</td><td><strong>Malignes :</strong> primitives — <span><span class=\"nc-orange_bg nc-bold\">carcinome hépatocellulaire</span></span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> ; secondaires — <span><span class=\"nc-orange\">métastases</span></span> ; hémopathie maligne (très rare) ; <br><strong>Bénignes :</strong> polykystose hépatique ou hépatorénale ; autres tumeurs bénignes (<span>hépatomégalie</span> exceptionnelle)</td></tr>\n          <tr><td>Atteintes infectieuses</td><td><span>Abcès hépatique</span> amibien ou <span>bactérien</span> ; <span>lésion parasitaire</span> (hydatidose)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Masses abdominales palpables selon le siège</h4>\n      <table>\n        <thead><tr><th>Siège</th><th>Organe</th><th>Cause</th></tr></thead>\n        <tbody>\n          <tr><td>Ép<span>iga</span>stre</td><td>Estomac, pancréas, foie</td><td><span><span class=\"nc-orange_bg nc-bold\">Tumeur gastrique</span></span> ; tumeur ou pseudo-kyste pancréatique (rarement palpables) ; <span>hépatomégalie</span> aux dépens du foie gauche</td></tr>\n          <tr><td><span class=\"nc-purple\">Hypochondre droit</span></td><td>Foie, <span>vésicule</span> biliaire</td><td><span>Hépatomégalie</span> ; obstacle biliaire du bas cholédoque (ex. cancer de la tête du pancréas) ; <span><span class=\"nc-orange_bg\">tumeur maligne de la vésicule</span></span></td></tr>\n          <tr><td>Hypochondre et flanc gauches</td><td>Rate</td><td><span>Splénomégalie</span></td></tr>\n          <tr><td>Fosse iliaque droite</td><td>Cæcum, ovaire droit</td><td><span>Cancer du côlon droit</span> ; <span>maladie de Crohn</span> (iléite, <span><span class=\"nc-blue_bg\">abcès</span></span>) ; <span><span class=\"nc-blue_bg\">abcès</span></span> appendiculaire (rare) ; kyste ovarien ; <span><span class=\"nc-blue_bg\">tumeur</span> ovarienne</span></td></tr>\n          <tr><td>Fosse iliaque gauche</td><td>S<span>igm</span>oïde, ovaire gauche</td><td><span>Constipation</span> ; <span>tumeur du sigmoïde</span> ; s<span>igm</span>oïdite ; kyste ovarien ; <span>tumeur ovarienne</span></td></tr>\n          <tr><td>Région ombilicale</td><td>Aorte, <span class=\"nc-purple nc-bold\">côlon transverse</span>, grêle</td><td><span>Anévrysme de l’aorte abdominale</span> ; <span>cancer colique</span> ; <span class=\"nc-blue_bg\">tumeur</span> du grêle (rare)</td></tr>\n          <tr><td>Hypogastre</td><td>Utérus, vessie</td><td><span><span class=\"nc-yellow_bg\">Grossesse</span></span> ; <span class=\"nc-orange_bg nc-bold\">fibromyome utérin</span> ; <span><span class=\"nc-orange_bg\">cancer de l’endomètre</span></span> ; <span class=\"nc-yellow_bg\">globe vésical</span> ; <span><span class=\"nc-blue_bg\">tumeur</span> vésicale</span></td></tr>\n          <tr><td>Ubiquitaire</td><td>Péritoine, ganglions, paroi</td><td><span>Carcinose péritonéale</span> ; <span>adénopathies</span> (lymphome, métastases) ; <span class=\"nc-orange\">hernies</span> et <span class=\"nc-orange\">éventrations</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Hépatomégalie</span> selon le caractère focal ou non de l’imagerie</h4>\n      <table>\n        <thead><tr><th>Profil</th><th>Étiologie</th><th>Repères clinico-bio-radiologiques</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"6\"><strong>Sans <span>lésion</span> focale</strong></td><td><span><span class=\"nc-orange_bg\">Stéatose</span></span></td><td><span><span class=\"nc-green\">Alcool</span></span>, <span><span class=\"nc-orange\">syndrome métabolique</span></span> ; <span>parenchyme hépatique hyperéchogène</span></td></tr>\n          <tr><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span></td><td>FdR de <span class=\"nc-orange_bg\">cirrhose</span>, signes d’<span>IHC</span> et/ou d’<span><span class=\"nc-red nc-bold\">HTP</span></span> ; clinique : <span><span class=\"nc-red nc-bold\">foie dur à la palpation</span></span>, <span><span class=\"nc-red nc-bold\">HMG à bord tranchant</span></span> ; écho : <span>contours bosselés</span>, <span>hépatomégalie</span> <span class=\"nc-green\">diffuse</span> ou <span class=\"nc-green\">sectorielle</span>, parfois absente</td></tr>\n          <tr><td><span><span class=\"nc-orange\">Insuffisance cardiaque</span></span></td><td>FdR, cardiopathie connue, signes d’<span><span class=\"nc-orange\">insuffisance cardiaque</span></span> ; <span>veines hépatiques dilatées</span> à l’imagerie</td></tr>\n          <tr><td><span><span class=\"nc-orange_bg\">Cholestase chronique</span></span></td><td><span>Prurit</span>, <span>ictère</span> ; <span>dilatation des voies biliaires</span></td></tr>\n          <tr><td><span>Infiltration tumorale</span></td><td><span><span class=\"nc-red nc-bold\">Altération de l’état général</span></span> ; <span>hémopathies</span> (lymphome), <span>cancer du sein</span> (rare)</td></tr>\n          <tr><td><span>Syndrome de Budd-Chiari</span></td><td><span><span class=\"nc-blue_bg\">Ascite</span></span> ; <span><span class=\"nc-blue_bg\">veines hépatiques non visualisées</span></span><span class=\"nc-blue_bg\"> à l’imagerie</span></td></tr>\n          <tr><td rowspan=\"3\"><strong>Avec <span>lésion</span> focale</strong></td><td><span><span class=\"nc-blue_bg\">Tumeur</span> hépatique</span></td><td><strong>Bénigne :</strong> polykystose hépatique ou hépato-rénale (<span>les</span> autres tumeurs bénignes causent rarement une HMG) ; <strong>Maligne :</strong> <span><span class=\"nc-red_bg\">CHC</span></span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> ; <strong><span class=\"nc-red_bg\">Secondaire</span> :</strong> <span class=\"nc-red nc-bold\">contexte de cancer</span> connu, signes en lien avec le primitif</td></tr>\n          <tr><td><span>Abcès hépatique</span></td><td><span>Syndrome septique</span> → <span><span class=\"nc-purple_bg\">abcès</span></span><span class=\"nc-purple_bg\"> amibien ou </span><span><span class=\"nc-purple_bg\">bactérien</span></span></td></tr>\n          <tr><td><span>Parasitoses</span></td><td>Séjour en <span>zone d’endémie</span> (<span>hydatidose</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span> · 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 234 — <span><span class=\"nc-orange\">Insuffisance cardiaque</span></span> · 219 — Pathologie du fer · 275 — <span>Splénomégalie</span> · 308 — <span class=\"nc-blue_bg\">Tumeur</span> pancréas · 303 — <span class=\"nc-blue_bg\">Tumeur</span> estomac · 301 — <span class=\"nc-blue_bg\">Tumeur</span> colon - rectum · 306 — <span class=\"nc-blue_bg\">Tumeur</span> ovaire · 225 — Artériopathie oblitérante - anévrysme</em></p></div>"},{"i":"91190c043b12","n":276,"o":"276-3","u":"Diagnostic positif","t":"Connaître la démarche diagnostique devant une hépatomégalie et une masse abdominale","q":"Quels sont les points essentiels concernant la démarche diagnostique devant une hépatomégalie et une masse abdominale ?","a":"<div class=\"notion-course\"><p>La démarche est <span>clinique d’abord</span> : la <span>palpation</span> caractérise la <span>masse</span> — <span>siège</span>, <span>taille</span>, <span>consistance</span>, <span>mobilité</span> — puis l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span> abdominale</span>, réalisée dans le prolongement de l’examen clinique, <span>confirme l’hépatomégalie</span>, écarte <span>les</span> autres <span>masses abdominales</span> et oriente l’étiologie.</p>\n      <p>Devant une <span>hépatomégalie</span>, l’<span>échographie</span> distingue <strong>trois profils</strong> qui commandent la suite des explorations.</p>\n      <table>\n        <thead><tr><th>Profil échographique</th><th>Orientation étiologique</th></tr></thead>\n        <tbody>\n          <tr><td><span>Hépatomégalie</span> <span><span class=\"nc-green\">diffuse</span> et <span class=\"nc-green\">homogène</span></span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span>, <span><span class=\"nc-orange_bg\">stéatose</span> / stéato-hépatite</span>, <span><span class=\"nc-blue_bg\">foie cardiaque</span></span>, <span>hépatite aiguë ou chronique</span>, <span>hémochromatose</span>, <span><span class=\"nc-orange_bg\">cholestase chronique</span></span></td></tr>\n          <tr><td><span>Hépatomégalie</span> <span><span class=\"nc-green\">sectorielle</span> mais <span class=\"nc-green\">homogène</span></span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span> (diagnostic le plus fréquent) ; plus rarement, <span>hypertrophie compensatrice</span> répondant à l’atrophie d’un autre secteur (<span class=\"nc-orange\">obstruction</span> des voies biliaires, des veines hépatiques ou portes du secteur atrophié)</td></tr>\n          <tr><td><span><span class=\"nc-green_bg\">Hépatomégalie</span></span><span class=\"nc-green_bg\"> </span><span><span class=\"nc-green_bg\">hétérogène</span></span></td><td>Doit faire chercher une <span><span class=\"nc-red_bg nc-bold\">tumeur du foie</span></span>, traduite par des <span><span class=\"nc-blue nc-bold\">nodules</span></span> ou des <span><span class=\"nc-blue nc-bold\">plages de parenchyme anormal</span></span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">⚠️ Toute <span><span class=\"nc-green_bg\">hépatomégalie hétérogène</span> doit faire chercher une <span class=\"nc-red_bg nc-bold\">tumeur du foie</span></span> jusqu’à preuve du contraire.</div>\n      <p>Lorsque la confrontation <span>clinique</span>, <span>biologique</span> et <span>radiologique</span> ne permet pas d’établir la cause, la <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span></span> est indiquée.</p></div>"},{"i":"1ea1fe3f180e","n":276,"o":"276-5","u":"Examens complémentaires","t":"Connaître les différents examens biologiques et radiologiques à réaliser en première intention devant une masse abdominale en fonction de l’étiologie suspectée","q":"Quels sont les points essentiels concernant les différents examens biologiques et radiologiques à réaliser en première intention devant une masse abdominale en fonction de l’étiologie suspectée ?","a":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-blue nc-bold\">masse abdominale</span></span>, l’examen complémentaire de référence est la <span><span class=\"nc-blue\">TDM</span> abdomino-pelvienne injectée</span>. Devant une <span>hépatomégalie</span>, l’exploration de <span>première intention</span> associe un bilan <span>biologique</span> simple et une <span><span class=\"nc-blue_bg nc-bold\">échographie</span> <span class=\"nc-blue_bg nc-bold\">abdominale</span></span>.</p>\n      <div class=\"callout callout-info\">📌 L’examen complémentaire de <strong><span>première intention</span> devant une <span><span class=\"nc-blue nc-bold\">masse</span></span><span class=\"nc-blue nc-bold\"> abdominale</span></strong> est la <span><span class=\"nc-blue\">TDM</span> abdomino-pelvienne injectée</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de <span>première intention</span> d’une <span>hépatomégalie</span></h4>\n      <table>\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Clinique</td><td>Le <span class=\"nc-red nc-bold\">foie</span> palpable définit l’<span>hépatomégalie</span> en pratique (un <span class=\"nc-red nc-bold\">foie</span> palpable est le plus souvent pathologique) ; la mesure de la <span>flèche hépatique</span> (HMG si <span><span class=\"nc-red nc-bold\">&gt; 12 cm</span></span> sur la ligne médioclaviculaire) n’a plus d’intérêt clinique ; une <span>masse</span> de l’<span class=\"nc-purple\">hypochondre droit</span> ou de l’ép<span>iga</span>stre <span class=\"nc-red nc-bold\">mobile avec la respiration</span> est rattachée au <span class=\"nc-red nc-bold\">foie</span></td></tr>\n          <tr><td>Biologie</td><td><span><span class=\"nc-blue_bg\">NFS</span></span>, <span><span class=\"nc-blue_bg\">bilan hépatique</span></span>, <span>TP</span>, <span><span class=\"nc-blue_bg\">albumine</span></span> — à la recherche de signes d’<span><span class=\"nc-orange nc-bold\">insuffisance hépatique</span></span></td></tr>\n          <tr><td><span>Échographie <span class=\"nc-blue_bg nc-bold\">abdominale</span></span></td><td>Mesure l’<span>hépatomégalie</span>, écarte <span>les</span> diagnostics différentiels (autres masses abdominales) et oriente l’étiologie</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Orientation étiologique de l’<span>échographie</span></h4>\n      <table>\n        <thead><tr><th>Signe échographique</th><th>Étiologie évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-blue\">Foie hyperéchogène</span></span></td><td><span><span class=\"nc-orange_bg\">Stéatose</span></span></td></tr>\n          <tr><td><span>Contours bosselés, <span class=\"nc-red nc-bold\">dysmorphie</span></span> (<span class=\"nc-blue nc-bold\">atrophie</span> du <span class=\"nc-purple nc-bold\">lobe droit</span>, <span class=\"nc-blue nc-bold\">hypertrophie</span> du <span class=\"nc-purple nc-bold\">lobe gauche</span>) avec signes d’<span><span class=\"nc-orange_bg nc-bold\">hypertension</span></span><span class=\"nc-orange_bg nc-bold\"> portale</span></td><td><span><span class=\"nc-orange_bg\">Cirrhose</span></span></td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Dilatation des veines hépatiques</span></span></td><td><span><span class=\"nc-orange_bg\">Insuffisance cardiaque droite</span></span></td></tr>\n          <tr><td><span>Dilatation des voies biliaires intra-hépatiques</span></td><td><span><span class=\"nc-orange_bg\">Cholestase</span></span><span class=\"nc-orange_bg\"> chronique</span></td></tr>\n          <tr><td><span>Nodule hétérogène</span> à <span class=\"nc-red nc-bold\">plages hyper et hypoéchogènes</span></td><td><span><span class=\"nc-orange_bg nc-bold\">Carcinome hépatocellulaire</span></span> (<span>nodule</span> suspect sur <span>cirrhose</span>)</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Exploration de seconde intention selon le contexte</h4>\n      <ul>\n        <li><strong>Absence de <span>lésion</span> focale :</strong> <span>sérologies</span> des <span><span class=\"nc-purple\">hépatites</span> virales</span>, <span>hépatite auto-immune</span>, bilan de <span>surcharge en fer</span> ; <span>élastométrie</span> et test sanguin de fibrose si <span>stéatose</span> ; <span>cholangio-IRM</span> ou <span>TDM</span> injectée si maladie biliaire suspectée</li>\n        <li><strong><span>Lésion</span> focale :</strong> <span><span class=\"nc-blue_bg\">TDM / IRM</span></span> ; <span><span class=\"nc-purple nc-bold\">sérologie des échinococcoses</span></span> si kyste hépatique ; <span><span class=\"nc-purple nc-bold\">hémocultures</span></span> et <span>sérologie <em>Entamoeba histolytica</em></span> si <span>abcès</span> hépatique</li>\n        <li><strong>Bilan non concluant :</strong> <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span></span> si clinique, biologie et imagerie ne permettent pas d’établir la cause</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span> · 278 — <span>Ictère</span></em></p></div>"},{"i":"05094137e65c","n":276,"o":"276-6","u":"Examens complémentaires","t":"Connaître les indications et contre-indications de la ponction et de la biopsie de foie","q":"Quels sont les points essentiels concernant les indications et contre-indications de la ponction et de la biopsie de foie ?","a":"<div class=\"notion-course\"><p>La <span><span class=\"nc-blue_bg\">ponction-biopsie hépatique</span> (PBH)</span> est indiquée lorsque la clinique, la biologie et l’imagerie ne permettent pas d’établir la cause d’une <span>hépatomégalie</span>. Trois voies d’abord sont possibles, choisies selon le <span>terrain</span> et <span>les</span> <span>contre-indications</span>.</p>\n      <div class=\"callout callout-info\">📌 <strong>Indication :</strong> <span>démarche diagnostique non concluante</span> — la <span>PBH</span> est indiquée lorsque <span>clinique</span>, <span>biologie</span> et <span>imagerie</span> ne permettent pas d’établir la cause d’une <span>hépatomégalie</span>.</div>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Voies de prélèvement</h4>\n      <table>\n        <thead><tr><th>Voie</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span>Percutanée</span></td><td>Voie de <strong><span>première intention</span></strong> ; <span>guidage échographique</span> le plus souvent ; <span>anesthésie locale</span></td></tr>\n          <tr><td><span>Transjugulaire</span></td><td>Voie <span>transveineuse</span> ; <strong>moins de risque <span>hémorragique</span></strong> ; <span>anesthésie locale</span> ; <span>ne permet pas de biopsier une lésion focale</span></td></tr>\n          <tr><td><span>Chirurgicale</span></td><td>Réservée à des situations particulières</td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span>Contre-indications</span></h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Contre-indications</th></tr></thead>\n        <tbody>\n          <tr><td>Voie percutanée (faire alors privilégier la voie transveineuse)</td><td><span><span class=\"nc-blue_bg\">Ascite</span>, même minime</span> ; <span>plaquettes &lt; <span>60 G/L</span></span> ; <span><span class=\"nc-red nc-bold\">TP &lt; </span><span><span class=\"nc-red nc-bold\">50 %</span></span></span> ; <span><span class=\"nc-red nc-bold\">TCA &gt; </span><span><span class=\"nc-red nc-bold\">1,5</span></span></span> ; <span class=\"nc-pink_bg\">hémodialyse</span> ; <span>antiagrégants plaquettaires</span>, <span><span class=\"nc-pink_bg\">anticoagulants</span></span>, <span><span class=\"nc-pink_bg\">AINS</span></span></td></tr>\n          <tr><td>Voie transveineuse</td><td><span>Thrombose des 3 veines sus-hépatiques</span></td></tr>\n          <tr><td>Dans tous <span>les</span> cas</td><td><span>Dilatation des voies biliaires intra-hépatiques</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Où prélever</h4>\n      <ul>\n        <li><strong><span>Hépatomégalie <span class=\"nc-green\">diffuse</span></span> :</strong> la <span>PBH</span> peut être faite <strong><span class=\"nc-red nc-bold\">en tout point</span></strong></li>\n        <li><strong><span><span class=\"nc-green_bg\">Hépatomégalie hétérogène</span></span> :</strong> prélèvement sur la <span>lésion focale</span> + <span><span class=\"nc-red nc-bold\">1 point</span></span><span class=\"nc-red nc-bold\"> du reste du parenchyme</span> (<span>2 prélèvements</span>)</li>\n        <li><strong><span>Abcès hépatique volumineux</span> :</strong> <span><span class=\"nc-blue nc-bold\">ponction ± drainage</span></span><span class=\"nc-blue nc-bold\"> sous </span><span><span class=\"nc-blue nc-bold\">contrôle échographique</span></span></li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ <strong>Complications de la <span>PBH</span> :</strong> <span><span class=\"nc-red_bg\">douleurs abdominales</span></span> ; <span><span class=\"nc-red_bg\">effraction pleurale ou biliaire</span></span> ; <span><span class=\"nc-red_bg\">saignement</span></span> (<span><span class=\"nc-red_bg\">hématome</span></span>, <span><span class=\"nc-red_bg\">hémopéritoine</span></span>, <span><span class=\"nc-red_bg\">choc hémorragique</span></span>). Elles justifient une <span>surveillance FC/PA</span> et un <span>alitement</span> pendant <span>≥ 6 h</span>.</div><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>La biopsie hépatique n’est pas automatique devant toute hépatomégalie inexpliquée. Indication, voie et risque hémorragique dépendent du bilan ; ne pas ponctionner à l’aveugle une lésion vasculaire ou hydatique suspectée. L’<span class=\"nc-blue_bg\">ascite</span> et les antithrombotiques imposent une évaluation, pas une règle unique pour toute voie de biopsie.</li></ul></div></div>"},{"i":"2c09f86dca57","n":276,"o":"276-7","u":"Contenu multimédia","t":"Tomodensitométrie de carcinome hépatocellulaire (CHC) typique chez un patient porteur d’une cirrhose","q":"Quels sont les points essentiels concernant tomodensitométrie de carcinome hépatocellulaire (CHC) typique chez un patient porteur d’une cirrhose ?","a":"<div class=\"notion-course\"><p>Chez un patient porteur d’une <span><span class=\"nc-orange_bg nc-bold\">cirrhose</span></span>, tout <span>nodule</span> est suspect : il s’intègre dans le <strong><span>dépistage</span> du <span><span class=\"nc-orange_bg nc-bold\">carcinome</span></span><span class=\"nc-orange_bg nc-bold\"> hépatocellulaire</span> (CHC)</strong> par <span>échographie</span> semestrielle. Un <span>nodule</span> détecté justifie une <span>imagerie en coupe injectée</span> (<span>TDM</span> ou <span>IRM</span>).</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> du CHC typique</h4>\n      <table>\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span>nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td>Sans injection</td><td><span><span class=\"nc-blue_bg\">Nodule</span></span><span class=\"nc-blue_bg\"> </span><span><span class=\"nc-blue_bg\">iso ou hypodense</span></span></td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">artériel</span></span></td><td><span><span class=\"nc-blue_bg\">Hyperdensité</span></span> du <span>nodule</span> — <span><span class=\"nc-red nc-bold\">wash-in</span></span> (rehaussement intense)</td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">portal</span></span></td><td>Lavage du contraste, aspect <span>hypovasculaire</span> — <span><span class=\"nc-red nc-bold\">wash-out</span></span></td></tr>\n        </tbody>\n      </table>\n      <p>Le CHC présente typiquement une artérialisation de sa vascularisation. Tous les CHC ne montrent pas un rehaussement <span class=\"nc-red\">artériel</span> typique ; interpréter la cinétique complète et le terrain.</p>\n      \n      <div class=\"callout callout-info\">📌 Un <span>nodule</span> de <span><span class=\"nc-red nc-bold\">&gt; 1 cm</span></span> présentant <span><span class=\"nc-red nc-bold\">wash-in</span></span> et <span><span class=\"nc-red nc-bold\">wash-out</span></span>, développé sur une <span><span class=\"nc-red nc-bold\">cirrhose certaine</span></span> et validé en <strong><span>RCP</span></strong>, permet un diagnostic non invasif de <span class=\"nc-orange\">CHC</span>, sans <span>biopsie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p></div>"},{"i":"753940e67b33","n":276,"o":"276-8","u":"Contenu multimédia","t":"Tomodensitométrie de métastases hépatiques","q":"Quels sont les points essentiels concernant tomodensitométrie de métastases hépatiques ?","a":"<div class=\"notion-course\"><p>Devant une <span><span class=\"nc-blue_bg\">tumeur</span> hépatique solide</span> sans maladie chronique du foie documentée, l’analyse repose sur la <span>cinétique de prise du produit de contraste</span> en <span><span class=\"nc-blue\">échographie</span></span><span class=\"nc-blue\"> de contraste</span>, <span><span class=\"nc-blue\">TDM</span></span> ou <span><span class=\"nc-blue\">IRM</span></span>, et sur la recherche d’un <span><span class=\"nc-red nc-bold\">contexte de cancer</span> extra-hépatique</span> (sexe, âge, cancer connu).</p>\n      <p>Le <span>contexte d’un cancer extra-hépatique connu</span> pèse fortement en faveur du diagnostic de métastase. La <span>TEP-FDG</span> (ou <span>TEP</span>-choline), en cas de <span>lésion</span> hépatique isolée, aide au <span>diagnostic différentiel</span> entre <span>métastase</span>, <span><span class=\"nc-red_bg\">cholangiocarcinome</span></span> et <span class=\"nc-blue_bg\">tumeur</span> bénigne.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> des <span class=\"nc-orange\">métastases</span> hépatiques</h4>\n      <table>\n        <thead><tr><th>Temps d’acquisition</th><th>Aspect du <span>nodule</span></th></tr></thead>\n        <tbody>\n          <tr><td><span>Temps <span class=\"nc-red\">artériel</span></span></td><td><span>Absence de rehaussement</span> de la <span>lésion</span></td></tr>\n          <tr><td><span>Temps <span class=\"nc-red\">portal</span></span></td><td><span>Absence de rehaussement</span> de la <span>lésion</span></td></tr>\n        </tbody>\n      </table>\n      \n      <div class=\"callout callout-info\">📌 Une <span>lésion</span> hépatique <span>sans rehaussement aux temps <span class=\"nc-red\">artériel</span> et <span class=\"nc-red\">portal</span></span> oriente vers une <span><span class=\"nc-orange\">métastase</span></span> ou un <span class=\"nc-orange\">adénome hépatocellulaire</span> ; le <span>contexte oncologique</span> (cancer extra-hépatique connu) tranche.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p></div>"},{"i":"ac6ed1029fe2","n":276,"o":"276-9","u":"Contenu multimédia","t":"Tomodensitométrie de kyste hépatique typique","q":"Quels sont les points essentiels concernant tomodensitométrie de kyste hépatique typique ?","a":"<div class=\"notion-course\"><p>Devant une <span>lésion hépatique kystique</span> sans maladie chronique du foie, l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span></span> détermine si la <span>lésion</span> est un <strong><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></strong>. <span>Les</span> principales tumeurs kystiques à connaître sont : le <span class=\"nc-orange nc-bold\">kyste biliaire simple</span>, les kystes parasitaires (<span>hydatidose</span>, échinococcose alvéolaire), les <span>abcès</span> amibiens, les <span>abcès</span> à pyogènes et les tumeurs nécrosées.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Critères échographiques du <span class=\"nc-orange nc-bold\">kyste biliaire simple</span></h4>\n      <ul>\n        <li><span>Lésion</span> <span>parfaitement liquidienne</span> (anéchogène, avec renforcement postérieur)</li>\n        <li><span><span class=\"nc-red nc-bold\">Absence de toute paroi ou cloison interne</span></span></li>\n      </ul>\n      <p>Si l’<span><span class=\"nc-blue_bg nc-bold\">échographie</span></span> confirme ces critères, le diagnostic de <span><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></span> est établi. On réalise néanmoins des <span><span class=\"nc-purple\">tests sérologiques d’hydatidose</span></span> chez <span>les</span> sujets ayant vécu en zone d’endémie au <span>contact</span> de chiens.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Sémiologie <span>TDM</span> du <span class=\"nc-orange nc-bold\">kyste biliaire simple</span> typique</h4>\n      <table>\n        <thead><tr><th>Critère</th><th>Aspect typique</th></tr></thead>\n        <tbody>\n          <tr><td>Forme</td><td><span>Lésion</span> <span>arrondie, à contours nets</span></td></tr>\n          <tr><td>Densité spontanée</td><td><span>Densité hydrique</span> homogène</td></tr>\n          <tr><td>Paroi</td><td><span>Paroi fine, voire invisible</span> ; pas de cloison interne</td></tr>\n          <tr><td>Après injection</td><td><span>Aucun rehaussement</span> (ni de la <span>lésion</span>, ni d’une paroi)</td></tr>\n        </tbody>\n      </table>\n      \n      <p>Si l’<span>échographie</span> ne répond pas aux critères du kyste simple, la <span>lésion</span> est précisée par <span><span class=\"nc-blue\">TDM</span>, <span class=\"nc-blue\">IRM</span> ou <span class=\"nc-blue\">échographie de contraste</span></span> : il peut alors s’agir d’une <span class=\"nc-blue_bg\">tumeur</span> bénigne à potentiel malin, d’une <span><span class=\"nc-blue_bg\">tumeur</span> maligne</span>, d’un <span>kyste hydatique</span> ou d’un <span class=\"nc-orange nc-bold\">kyste biliaire simple</span> modifié par une hémorragie intrakystique.</p>\n      <div class=\"callout callout-info\">📌 Le <span><span class=\"nc-orange nc-bold\">kyste biliaire simple</span></span> est un diagnostic d’imagerie : <span>lésion</span> <span>parfaitement liquidienne</span>, <span>sans paroi ni cloison</span>, <span>sans rehaussement</span>. Toute paroi épaisse, cloison interne, composante tissulaire ou rehaussement doit remettre en cause le diagnostic et faire évoquer un <span>kyste hydatique</span>, une <span><span class=\"nc-blue_bg\">tumeur</span> kystique</span> (bénigne à potentiel malin ou maligne) ou un <span><span class=\"nc-blue_bg\">abcès</span></span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 304 — <span class=\"nc-red_bg nc-bold\">Tumeur du foie</span> · 279 — <span><span class=\"nc-orange_bg\">Cirrhose</span></span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Un kyste simple typique ne justifie pas systématiquement une sérologie hydatique ; rechercher une exposition et des signes atypiques. Éviter toute ponction avant caractérisation si une hydatidose est possible.</li></ul></div></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181a89cc6c3fcf8b72c1d?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
